#!/usr/bin/env bash
# Tests for .claude/scripts/guard-generated.sh, the Claude Code PreToolUse hook
# that asks the user before an Edit/Write of a generated file (a `Code generated … DO NOT EDIT`
# line in the first five lines).
set -uo pipefail
# shellcheck source=../lib/assert.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib/assert.sh"

GUARD="$REPO_ROOT/.claude/scripts/guard-generated.sh"

# The guard's verdict (ask / pass) for an Edit payload on path $1.
guard_status() {
  jq -cn --arg p "$1" '{tool_name: "Edit", tool_input: {file_path: $p}}' | verdict bash "$GUARD"
}

# Why this test is important:
#   - Go generators (mockgen, wire, protoc) all use this header; an edit to
#     their output is lost on the next regenerate.
# What it tests:
#   - A file headed `// Code generated by mockgen. DO NOT EDIT.` is blocked,
#     and the decision's reason names the file.
test_asks_go_generated() {
  printf '// Code generated by mockgen. DO NOT EDIT.\npackage mocks\n' > "$T/mock.go"
  assert_eq ask "$(guard_status "$T/mock.go")" "a mockgen file"
  local reason
  reason=$(jq -cn --arg p "$T/mock.go" '{tool_input: {file_path: $p}}' | bash "$GUARD" 2>/dev/null |
    jq -r '.hookSpecificOutput.permissionDecisionReason')
  assert_contains "$reason" "generated file" "reason"
  assert_contains "$reason" "$T/mock.go" "reason names the file"
}

# Why this test is important:
#   - A one-line generated file often has no trailing newline; `read` returns
#     non-zero on that partial line, so a naive loop never tests it.
# What it tests:
#   - A file whose only line is the marker, without a newline, asks.
test_asks_marker_without_trailing_newline() {
  printf '// Code generated by mockgen. DO NOT EDIT.' > "$T/one.go"
  assert_eq ask "$(guard_status "$T/one.go")" "an unterminated marker line"
}

# Why this test is important:
#   - claude-gen puts its marker inside frontmatter (line 2), not on line 1.
# What it tests:
#   - A rule file with the marker as a YAML comment on line 2 asks.
test_asks_marker_in_frontmatter() {
  printf -- '---\n# Code generated by claude-gen; DO NOT EDIT.\npaths: ["*.go"]\n---\nbody\n' > "$T/rule.md"
  assert_eq ask "$(guard_status "$T/rule.md")" "a generated rule"
}

# Why this test is important:
#   - The hook runs on every edit in every project; it must not interrupt normal work.
# What it tests:
#   - A plain source file is allowed.
test_allows_plain_file() {
  printf 'package main\n' > "$T/main.go"
  assert_eq pass "$(guard_status "$T/main.go")" "a plain file"
}

# Why this test is important:
#   - Docs and tests mention the phrase; only a header marks a file generated.
# What it tests:
#   - The phrase on line 9 does not ask.
test_allows_late_mention() {
  printf '1\n2\n3\n4\n5\n6\n7\n8\nCode generated by x; DO NOT EDIT.\n' > "$T/notes.md"
  assert_eq pass "$(guard_status "$T/notes.md")" "a late mention"
}

# Why this test is important:
#   - Write creates new files; a missing path is not generated output.
# What it tests:
#   - A nonexistent path and an empty payload path are allowed.
test_allows_missing_path() {
  assert_eq pass "$(guard_status "$T/new.md")" "a new file"
  assert_eq pass "$(guard_status "")" "no path"
}

# Why this test is important:
#   - A guard that allows what it cannot read fails open.
# What it tests:
#   - Malformed JSON asks.
test_asks_bad_json() {
  assert_eq ask "$(printf 'not json' | verdict bash "$GUARD")" "malformed payload"
}

# Why this test is important:
#   - Without jq the hook cannot read the payload; it must fail toward the
#     user's prompt, not open.
# What it tests:
#   - With no jq on PATH the guard asks.
test_asks_without_jq() {
  assert_eq ask "$(printf '{"tool_input":{"file_path":"/x"}}' | verdict env PATH="$T/empty" /bin/bash "$GUARD")" "without jq"
}

run_test test_asks_go_generated
run_test test_asks_marker_in_frontmatter
run_test test_asks_marker_without_trailing_newline
run_test test_allows_plain_file
run_test test_allows_late_mention
run_test test_allows_missing_path
run_test test_asks_bad_json
run_test test_asks_without_jq
finish
